    TStmtNode(Stmt s) or
    TAnnotatedExitNode(Callable c, Boolean normal) { exists(c.getBody()) } or
    TExitNode(Callable c) { exists(c.getBody()) } or
    TAssertThrowNode(AssertStmt s)

